                        model.model_validate(invalid)

def validate_graph_document(document: Mapping[str, Any]) -> None:
    """Validate the portable JSON graph document used by M1 and M3."""

    errors: list[str] = []

    graph_version = document.get("graph_version")
    if not isinstance(graph_version, str) or not graph_version:
        errors.append("graph_version must be a non-empty string")

    nodes = document.get("nodes")
    edges = document.get("edges")

    if not isinstance(nodes, list):
        errors.append("nodes must be a list")
        nodes = []
    if not isinstance(edges, list):
        errors.append("edges must be a list")
        edges = []

    nodes_by_id: dict[str, Mapping[str, Any]] = {}
    repository_count = 0

    for index, node in enumerate(nodes):
        prefix = f"nodes[{index}]"
        if not isinstance(node, Mapping):
            errors.append(f"{prefix} must be an object")
            continue

        node_id = node.get("id")
        node_type = node.get("type")

        if not isinstance(node_id, str) or not node_id:
            errors.append(f"{prefix}.id must be a non-empty string")
        elif node_id in nodes_by_id:
            errors.append(f"duplicate node id: {node_id}")
        else:
            nodes_by_id[node_id] = node

        if node_type not in NODE_TYPES:
            errors.append(f"{prefix}.type is unsupported: {node_type!r}")
        if node_type == "Repository":
            repository_count += 1

        for field in ("repo_key", "name", "qualified_name"):
            if not isinstance(node.get(field), str) or not node[field]:
                errors.append(f"{prefix}.{field} must be a non-empty string")

        if node.get("graph_version") != graph_version:
            errors.append(f"{prefix}.graph_version must match document graph_version")

        if not isinstance(node.get("properties"), Mapping):
            errors.append(f"{prefix}.properties must be an object")

        if node_type in SOURCE_BACKED_NODE_TYPES:
            if not isinstance(node.get("path"), str) or not node["path"]:
                errors.append(f"{prefix}.path is required for {node_type}")
            if not _valid_range(node.get("range")):
                errors.append(f"{prefix}.range is invalid for {node_type}")
        elif node_type == "Module":
            properties = node.get("properties") or {}
            if not properties.get("is_external"):
                if not isinstance(node.get("path"), str) or not node["path"]:
                    errors.append(f"{prefix}.path is required for internal Module")
                if not _valid_range(node.get("range")):
                    errors.append(f"{prefix}.range is invalid for internal Module")

    if repository_count != 1:
        errors.append(f"exactly one Repository node is required, got {repository_count}")

    edge_ids: set[str] = set()
    contains_adjacency: dict[str, list[str]] = defaultdict(list)
    call_counts: dict[str, int] = defaultdict(int)

    for index, edge in enumerate(edges):
        prefix = f"edges[{index}]"
        if not isinstance(edge, Mapping):
            errors.append(f"{prefix} must be an object")
            continue

        edge_id = edge.get("id")
        edge_type = edge.get("type")
        source_id = edge.get("source_id")
        target_id = edge.get("target_id")

        if not isinstance(edge_id, str) or not edge_id:
            errors.append(f"{prefix}.id must be a non-empty string")
        elif edge_id in edge_ids:
            errors.append(f"duplicate edge id: {edge_id}")
        else:
            edge_ids.add(edge_id)

        if edge_type not in EDGE_ENDPOINTS:
            errors.append(f"{prefix}.type is unsupported: {edge_type!r}")

        source = nodes_by_id.get(source_id)
        target = nodes_by_id.get(target_id)
        if source is None:
            errors.append(f"{prefix}.source_id does not exist: {source_id!r}")
        if target is None:
            errors.append(f"{prefix}.target_id does not exist: {target_id!r}")

        if source_id == target_id:
            errors.append(f"{prefix} must not be a self-loop")

        if source is not None and target is not None and edge_type in EDGE_ENDPOINTS:
            endpoint = (source.get("type"), target.get("type"))
            if endpoint not in EDGE_ENDPOINTS[edge_type]:
                errors.append(
                    f"{prefix} has invalid endpoints for {edge_type}: "
                    f"{endpoint[0]} -> {endpoint[1]}"
                )

        confidence = edge.get("confidence")
        if (
            isinstance(confidence, bool)
            or not isinstance(confidence, (int, float))
            or not 0.0 <= confidence <= 1.0
        ):
            errors.append(f"{prefix}.confidence must be within [0, 1]")

        if edge.get("graph_version") != graph_version:
            errors.append(f"{prefix}.graph_version must match document graph_version")

        provenance = edge.get("provenance")
        if not isinstance(provenance, Mapping):
            errors.append(f"{prefix}.provenance must be an object")
        else:
            for field in ("source_tool", "rule_id", "source_revision"):
                if not isinstance(provenance.get(field), str) or not provenance[field]:
                    errors.append(f"{prefix}.provenance.{field} is required")

        if not isinstance(edge.get("properties"), Mapping):
            errors.append(f"{prefix}.properties must be an object")

        if edge_type == "CONTAINS" and source_id and target_id:
            contains_adjacency[source_id].append(target_id)
        if edge_type == "CALLS" and source_id:
            call_counts[source_id] += 1

    errors.extend(_containment_cycle_errors(contains_adjacency))

    for node_id, node in nodes_by_id.items():
        if node.get("type") != "CallSite":
            continue
        properties = node.get("properties") or {}
        candidate_count = properties.get("candidate_count")
        if candidate_count != call_counts[node_id]:
            errors.append(
                f"CallSite {node_id!r} candidate_count={candidate_count!r} "
                f"but has {call_counts[node_id]} outgoing CALLS edges"
            )

    if errors:
        raise GraphValidationError(errors)

class ContextPayload(BaseModel):
    """Validated context bundle passed from retrieval to prompt assembly."""

    model_config = ConfigDict(extra="forbid")

    graph_version: str = Field(min_length=1)
    anchor_ids: list[str]
    items: list[ContextItem]
    total_token_count: int = Field(ge=0)
    token_budget: int = Field(gt=0)
    truncated: bool = False

    @model_validator(mode="after")
    def validate_budget_accounting(self) -> ContextPayload:
        calculated = sum(item.token_count for item in self.items)
        if self.total_token_count != calculated:
            raise ValueError(
                "total_token_count must equal the sum of item token_count values"
            )
        if self.total_token_count > self.token_budget:
            raise ValueError("total_token_count must not exceed token_budget")
        return self

class SourceRange(BaseModel):
    model_config = ConfigDict(extra="forbid")

    start_line: int = Field(ge=1)
    start_col: int = Field(ge=0)
    end_line: int = Field(ge=1)
    end_col: int = Field(ge=0)

    @model_validator(mode="after")
    def validate_order(self) -> SourceRange:
        if (self.end_line, self.end_col) < (self.start_line, self.start_col):
            raise ValueError("range end must not precede range start")
        return self

class GraphError(Exception):
    """Base error with a stable machine-readable code for the MCP boundary."""

    code = "GRAPH_ERROR"

    def __init__(self, message: str, *, details: dict[str, Any] | None = None) -> None:
        self.message = message
        self.details = details or {}
        super().__init__(message)

    def to_dict(self) -> dict[str, Any]:
        payload: dict[str, Any] = {"code": self.code, "message": self.message}
        if self.details:
            payload["details"] = self.details
        return payload

class NodeNotFoundError(GraphError, KeyError):
    code = "NODE_NOT_FOUND"

    def __init__(self, node_id: str, *, entity: str = "node") -> None:
        super().__init__(
            f"Unknown {entity}: {node_id}",
            details={"entity": entity, "node_id": node_id},
        )

def _words(text: str) -> set[str]:
    expanded = re.sub(r"([a-z])([A-Z])", r"\1 \2", text)
    return {match.lower() for match in _WORDS.findall(expanded)}

def _verify_snapshot(self) -> dict[str, bytes]:
        actual = {path.relative_to(self.root).as_posix() for path in self.root.rglob("*.py")
                  if not any(part in IGNORED_DIRECTORY_NAMES for part in path.parts)}
        if actual != set(self.files):
            raise GraphError("Source file set differs from graph snapshot; rebuild graph",
                             details={"reason": "source_snapshot_mismatch",
                                      "added": sorted(actual - set(self.files)),
                                      "missing": sorted(set(self.files) - actual)})
        sources = {}
        for relative, node in sorted(self.files.items()):
            path = PurePosixPath(relative)
            if path.is_absolute() or PureWindowsPath(relative).drive or ".." in path.parts or path.as_posix() != relative:
                raise GraphError("Invalid repository-relative graph source path")
            resolved = (self.root / relative).resolve()
            if not resolved.is_relative_to(self.root):
                raise GraphError("Graph source path escapes repository root")
            try:
                data = resolved.read_bytes()
            except OSError as error:
                raise GraphError("Cannot read graph source; rebuild graph", details={"path": relative}) from error
            if _hash(data) != node.get("content_hash"):
                raise GraphError("Source content differs from graph snapshot; rebuild graph", details={"path": relative})
            sources[relative] = data
        return sources

def _snippet(node: dict[str, Any], data: bytes) -> str:
        source_range = node["range"]
        start, end = source_range["start_byte"], source_range["end_byte"]
        if not 0 <= start <= end <= len(data):
            raise GraphError("Graph source byte range is out of bounds")
        for prefix, offset in (("start", start), ("end", end)):
            head = data[:offset]
            line = head.count(b"\n") + 1
            column = len(head.rsplit(b"\n", 1)[-1])
            if (line, column) != (source_range[f"{prefix}_line"], source_range[f"{prefix}_col"]):
                raise GraphError("Graph byte range does not match line/column metadata")
        snippet = data[start:end]
        if _hash(snippet) != node.get("content_hash"):
            raise GraphError("Graph snippet content hash mismatch; rebuild graph")
        try:
            return snippet.decode("utf-8")
        except UnicodeDecodeError as error:
            raise GraphError("Snippet cannot be decoded as UTF-8") from error

def _walk(
        self, starts: list[str], scores: dict[str, float],
    ) -> tuple[dict[str, tuple[int, float, tuple[str, ...]]], bool]:
        states: dict[str, tuple[int, float, tuple[str, ...]]] = {}
        queue = []
        ordered = sorted(set(starts), key=lambda node_id: (-scores.get(node_id, 1.0), node_id))
        limited = len(ordered) > self.config.max_candidates
        for node_id in ordered[:self.config.max_candidates]:
            confidence = scores.get(node_id, 1.0)
            states[node_id] = (0, confidence, ("TASK_ANCHOR",))
            heapq.heappush(queue, (0, -confidence, node_id, ("TASK_ANCHOR",)))
        while queue:
            distance, negative, node_id, rationale = heapq.heappop(queue)
            if states[node_id] != (distance, -negative, rationale) or distance >= self.config.max_hops:
                continue
            for target, edge_confidence, relation in self.adjacency[node_id]:
                path = rationale + (f"{relation}:{node_id}->{target}",)
                candidate = (distance + 1, min(-negative, edge_confidence), path)
                existing = states.get(target)
                if existing is not None and (existing[0], -existing[1], existing[2]) <= (
                    candidate[0], -candidate[1], candidate[2]
                ):
                    continue
                if existing is None and len(states) >= self.config.max_candidates:
                    limited = True
                    continue
                states[target] = candidate
                heapq.heappush(queue, (candidate[0], -candidate[1], target, candidate[2]))
        return states, limited
